  undoneAt: timestamp("undone_at", { withTimezone: true }), undoneBy: uuid("undone_by").references(() => authUsers.id),
}, (table) => [unique("wealth_events_workspace_id_request_id_key").on(table.workspaceId, table.requestId)]);

